请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-010

=== 用户原始指令 (query.txt) ===
整个点一下能跳到app的嘛，要显示已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个点一下能跳到app的嘛，要显示已连接",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "audio": {
      "title": {
        "type": "string",
        "description": "听书或音频入口的短标题。",
        "sampleValue": "阅读听书"
      },
      "status": {
        "type": "string",
        "description": "当前连接状态展示文本。",
        "sampleValue": "已连接"
      },
      "hint": {
        "type": "string",
        "description": "整卡点击后的入口提示。",
        "sampleValue": "点按打开"
      },
      "icon": {
        "type": "string",
        "description": "音乐或听书入口的本地图标资源路径。",
        "sampleValue": "resources/base/media/icon_music.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_music.png",
      "description": "音乐图标，适合表达听书、音频播放或音乐应用入口，彩色 PNG，适合浅色或柔和渐变表面。",
      "bindTo": "/audio/icon"
    }
  ]
}

